    if (['.js', '.mjs', '.cjs'].includes(ext)) kind = 'typescript-module'
    if (relPath.startsWith('src/') && (ext === '.js' || ext === '.jsx')) kind = 'typescript-module'

    let loc = 0
    try {
      const content = fs.readFileSync(absPath, 'utf-8')
      loc = content.split('\n').length
    } catch { /* ignore */ }

    return {
      path: relPath,
      kind,
      exports: [],
      imports: [],
      components: [],
      hooks: [],
      hasJsdoc: false,
      loc,
    }
  }

