export function getIncompleteSections1to7(data: FormData): { id: number; title: string; missing: string[] }[] {
  const validators = [
    validateSection1,
    validateSection2,
    validateSection3,
    validateSection4,
    validateSection5,
    validateSection6,
    validateSection7,
  ]

  const incomplete: { id: number; title: string; missing: string[] }[] = []
  validators.forEach((fn, i) => {
    const result = fn(data)
    if (!result.complete) {
      incomplete.push({
        id: i + 1,
        title: SECTION_LABELS[i].title,
        missing: result.missing,
      })
    }
  })
  return incomplete
}

export function getOverallProgress(data: FormData): { filled: number; total: number; percent: number } {
  const validators = [
    validateSection1,
    validateSection2,
    validateSection3,
    validateSection4,
    validateSection5,
    validateSection6,
    validateSection7,
  ]

  let filled = 0
  let total = 0
  for (const v of validators) {
    const result = v(data)
    filled += result.filled
    total += result.total
  }

  return {
    filled,
    total,
    percent: total === 0 ? 0 : Math.round((filled / total) * 100),
  }
}

